  FT["PH-H5167"] = {"id":"PH-H5167","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1988/ra_6670_1988.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"对第 1177 号共和国法的修改","en":"An Act Further Amending Certain Sections and Terms Used in Presidential Decree No. 1177, as amended, in Order to Institute a Modified Performance Budget System","orig":"An Act Further Amending Certain Sections and Terms Used in Presidential Decree No. 1177, as amended, in Order to Institute a Modified Performance Budget System"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6670","issuingBody":"Congress of the Philippines","promulgatedDate":"1988-08-04","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1988/ra_6670_1988.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5167-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 13 of P.D. 1177 is hereby amended to read as follows:\n\"Sec. 13. Submission of the Budget. — The President shall, in accordance with Section 22, Article VII of the Constitution, submit to the Congress within thirty (30) days from the opening of every regular session, as the basis of the General Appropriations Bill, a budget of expenditures and sources of financing, including receipts from existing and proposed revenue measures. Additional appropriations proposals may be submitted which correspond to part of the expenditure estimates submitted as part of the budget proposal: Provided, That continuing appropriations may be enacted for public works, highways and other infrastructure projects which require more than one year for construction. In such cases, revenue estimates for the future years shall be used in the evaluation of funding availability.\n\"The President may transmit to Congress, from time to time, such proposed supplemental or deficiency appropriations as are, in his judgment, (a) necessary on account of laws enacted after the transmission of the Budget, or (b) otherwise needed in the public interest.\""}},{"id":"PH-H5167-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 24 of the same decree is hereby amended to read as follows:\n\"Sec. 24. Appropriations for Personal Services. — Appropriations for personal services shall be considered as included in the amount specified for each budgetary program and project of each department, bureau, office or agency, and shall be itemized. The itemization of personal services shall be prepared by the Secretary for consideration and approval of the President as provided in Section 30 hereof: Provided, that the itemization of personal services shall be prepared for all agencies of the Legislative, Executive and Judicial Branches and the Constitutional bodies down to the division chief level and in the case of the Armed Forces of the Philippines and the Integrated National Police down to the rank of second lieutenant, except as may be otherwise approved by the President for positions concerned with national security matters: Provided, further, That appropriations for casual and/ or temporary employees shall be in lump-sum based on the number of man-hours to be rendered.\""}},{"id":"PH-H5167-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 26 of the same decree is hereby repealed."}},{"id":"PH-H5167-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 27 of the same decree is hereby amended to read as follows:\n\"Sec. 27. Infrastructure and Other Bills. — The public works, highways and other bills requiring appropriations may be filed at any time during the sessions of the Congress and shall be considered by the Congress upon their being reported out by the corresponding Committees.\""}},{"id":"PH-H5167-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Sections 28 and 29 of the same decree are hereby repealed."}},{"id":"PH-H5167-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section 30 of the same decree is hereby amended to read as follows:\n\"Sec. 30. Content of the General Appropriations Act. — The General Appropriations Act shall be presented in the form of budgetary programs and projects for each agency of the government, with the corresponding appropriations for each program and project, including statutory provisions of specific agency or general applicability. The General Appropriations Act shall contain an itemization of personal services which shall be prepared by the Secretary before enactment of the General Appropriations Act.\""}},{"id":"PH-H5167-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The following words, phrases or terms wherever they appear in Presidential Decree No. 1177, as amended, are hereby amended to read:\n(a) \" Ministry of the Budget \" shall read \" Department of the Budget and Management \";\n(b) \" Minister of Budget \" shall read \""}}],"pack":"ph-p73"};
  FT["PH-H5168"] = {"id":"PH-H5168","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1988/ra_6671_1988.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Renaming Barangay Caputatan in the Municipality of Maragondon, Province of Cavite, to Be Know as Barangay San Miguel and for Other Purposes","orig":"An Act Renaming Barangay Caputatan in the Municipality of Maragondon, Province of Cavite, to Be Know as Barangay San Miguel and for Other Purposes"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 6671","issuingBody":"Congress of the Philippines","promulgatedDate":"1988-09-05","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1988/ra_6671_1988.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5168-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Barangay Caputatan in the Municipality of Maragondon, Province of Cavite, is hereby renamed to Barangay San Miguel."}},{"id":"PH-H5168-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Local Government and Community Development, through the Provincial Board of Cavite, and the Municipal Council of Maragondon, Provincial of Cavite, is hereby directed to carry out the purpose of this act."}},{"id":"PH-H5168-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p73"};
