  FT["PH-H5170"] = {"id":"PH-H5170","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1988/ra_6673_1988.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the General Trias Elementary School in the Municipality of General Trias, Province of Cavite, to Paaralang Pang-Alaala Kay Diego Mojica (Diego Mojica Memorial School)","orig":"An Act Changing the Name of the General Trias Elementary School in the Municipality of General Trias, Province of Cavite, to Paaralang Pang-Alaala Kay Diego Mojica (Diego Mojica Memorial School)"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 6673","issuingBody":"Congress of the Philippines","promulgatedDate":"1988-09-05","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1988/ra_6673_1988.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5170-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the General Trials Elementary School in the Municipality of General Trias, Province of Cavite, is changed to Paaralang Pang-alaala kay Diego Mojica (Diego Mojica Memorial School)."}},{"id":"PH-H5170-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p73"};
  FT["PH-H5171"] = {"id":"PH-H5171","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1988/ra_6674_1988.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of Barangay Cobol, Municipality of Batac, Province of Ilocos Norte, to Barangay Petra Pimentel and for Some Other Purpose","orig":"An Act Changing the Name of Barangay Cobol, Municipality of Batac, Province of Ilocos Norte, to Barangay Petra Pimentel and for Some Other Purpose"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 6674","issuingBody":"Congress of the Philippines","promulgatedDate":"1988-09-05","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1988/ra_6674_1988.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5171-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Barangay Cobol in the Municipality of Batac, Province of Ilocos Norte, is hereby changed to Barangay Petra Pimentel."}},{"id":"PH-H5171-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p73"};
  FT["PH-H5172"] = {"id":"PH-H5172","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1988/ra_6675_1988.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":null,"en":"Generics Act of 1988.","orig":"Generics Act of 1988. An Act to Promote, Require and Ensure the Production of an Adequate Supply, Distribution, Use and Acceptance of Drugs and Medicines Identified by their Generic Names"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6675","issuingBody":"Congress of the Philippines","promulgatedDate":"1988-09-13","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1988/ra_6675_1988.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 15 条，缺 13）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5172-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title – This Act shall be known as the \" Generics Act of 1988. \""}},{"id":"PH-H5172-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Statement of Policy – It is hereby declared the policy of the State:\nTo promote, encourage and require the use of generic terminology in the importation, manufacture, distribution, marketing, advertising and promotion, prescription and dispensing of drugs;\nTo ensure the adequate supply of drugs with generic names at the lowest possible cost and endeavor to make them available for free to indigent patients;\nTo encourage the extensive use of drugs with generic names through a rational system of procurement and distribution;\nTo emphasize the scientific basis for the use of drugs, in order that health professionals may become more aware and cognizant of their therapeutic effectiveness; and To promote drug safety by minimizing duplication in medications and/or use of drugs with potentially adverse drug interactions."}},{"id":"PH-H5172-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of Terms – The following terms are herein defined for purposes of this Act:\n(1) \" Generic Name or Generic Terminology \" is the identification of drugs and medicines by their scientifically and internationally recognize active ingredients or by their official generic name as determined by the Bureau of Food and Drugs of the Department of Health.\n(2) \" Active Ingredient \" is the chemical component responsible for the claimed therapeutic effect of the pharmaceutical product.\n(3) \" Chemical Name \" is the description of the chemical structure of the drug or medicine and serves as the complete identification of a compound.\n(4) \" Drug Product \" is the finished product form that contains the active ingredients, generally but not necessarily in association with inactive ingredients.\n(5) \" Drug Establishment \" is any organization or company involved in the manufacture, importation, repacking and/or distribution of drugs or medicines.\n(6) \" Drug Outlets \" means drugstores, pharmacies, and any other business establishments which sell drugs or medicines.\n(7) \" Essential Drugs List \" or \"National Drug Formulary\" is a list of drugs prepared and periodically updated by the Department of Health on the basis of health conditions obtaining in the Philippines as well as on internationally accepted criteria. It shall consist of a core list and a complementary list.\n(8) \" Core List \" is a list of drugs that meets the health care needs of the majority of the population.\n(9) \" Complementary List \" is a list of alternative drugs used when there is no response to the core essential drug or when there is hypersensitivity reaction to the core essential drug or when for one reason or another, the core essential drug cannot be given.\n(10) \" Brand Name \" is the proprietary name given by the manufacturer to distinguish its product from those of competitors.\n(11) \" Generic Drugs \" are drugs not covered by patent protection and which are labeled solely by their international non-proprietary or generic name."}},{"id":"PH-H5172-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Use of Generic Terminology for Essential Drugs and Promotional Incentives. – (a) In the promotion of the generic names for pharmaceutical products, special consideration shall be given to drugs and medicines which are included in the Essential Drugs List to be prepared within one hundred eighty (180) days from approval of this Act and updated quarterly by the Department of Health on the basis of health conditions obtaining in the Philippines as well as on internationally accepted criteria.\n(b) The exclusive use of generic terminology in the manufacture, marketing and sales of drugs and medicines, particularly those in the Essential Drugs List, shall be promoted through such a system of incentives as the Board of Investments jointly with the Department of Health and other government agencies as may be authorized by law, shall promulgate in accordance with existing laws, within one hundred eighty (180) days after approval of this Act."}},{"id":"PH-H5172-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Posting and Publication – The Department of Health shall publish annually in at least two (2) newspapers of general circulation in the Philippines the generic names, and the corresponding brand names under which they are marketed, of all drugs and medicines available in the Philippines."}},{"id":"PH-H5172-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Who Shall Use Generic Terminology - (a) All government health agencies and their personnel as well as other government agencies shall use generic terminology or generic names in all transactions related to purchasing, prescribing, dispensing and administering of drugs and medicines.\n(b) All medical, dental and veterinary practitioners, including private practitioners, shall write prescriptions using the generic name. The brand name may be included if so desired.\n(c) Any organization or company involved in the manufacture, importation, repacking, marketing and/or distribution of drugs and medicines shall indicate prominently the generic name of the product. In the case of brand name products, the generic name shall appear prominently and immediately above the brand name in all product labels as well as in advertising and other promotional materials.\n(d) Drug outlets, including drugstores, hospital and non-hospital pharmacies and non-traditional outlets such as supermarkets and stores, shall inform any buyer about any and all other drug products having the same generic name, together with their corresponding prices so that the buyer may adequately exercise, his option.\nWithin one (1) year after approval of this Act, the drug outlets referred to herein, shall post in conspicuous places in their establishments, a list of drug products with the same generic name and their corresponding prices."}},{"id":"PH-H5172-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Provision on Quality, Manufacturer’s Identity and Responsibility – In order to assure responsibility for drug quality in all instances, the label of all drugs and medicines shall have the following: name and country of manufacture, dates of manufacture and expiration. The quality of such generically labeled drugs and medicines shall be duly certified by the Department of Health."}},{"id":"PH-H5172-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Required Production – Subject to the rules and regulations promulgated by the Secretary of Health, every drug manufacturing company operating in the Philippines shall be required to produce, distribute and make available to the general public the medicine it produces, in the form of generic drugs."}},{"id":"PH-H5172-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Rules and Regulations – The implementation of the provisions of this Act shall be in accordance with the rules and regulations to be promulgated by the Department of Health. Rules and regulations with penal sanctions shall be promulgated within one hundred eighty (180) days after approval of this Act and shall take effect fifteen (15) days after publication in the Official Gazette or in two (2) newspapers of general circulation."}},{"id":"PH-H5172-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Authority to Import – Within three (3) years from the effectivity of this Act, extendible by the President for another two (2) years and during periods of critical shortage and absolute necessity, the Department of Health is hereby authorized to import raw materials of which there is a shortage for the use of Filipino-owned or controlled drug establishments to be marketed and sold exclusively under generic nomenclature. The President may authorize the importation of raw materials tax and duty-free. The Secretary of Health shall ensure that the imported raw materials are allocated fairly and efficiently among Filipino-owned or controlled drug establishments. He shall submit to the Office of the President and to Congress a quarterly report on the quantity, kind and value of the raw materials imported."}},{"id":"PH-H5172-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Education Drive – The Department of Health jointly with the Department of Education, Culture and Sports, Philippine Information Agency and the Department of Local Government shall conduct a continuous information campaign for the public and a continuing education and training for the medical and allied medical professions on drugs with generic names as an alternative of equal efficacy to the more expensive brand name drugs. Such educational campaign shall include information on the illnesses or symptoms which each generically named drug is supposed to cure or alleviate, as well as its contraindications. The Department of Health with the assistance of the Department of Local Government and the Philippine Information Agency shall monitor the progress of the education drive, and shall submit regular reports to Congress."}},{"id":"PH-H5172-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Penalty – A) Any person who shall violate Section 6(a) or 6(b) of this Act shall suffer the penalty graduated hereunder, viz:\n(a) for the first conviction, he shall suffer the penalty of reprimand which shall be officially recorded in the appropriate books of the Professional Regulation Commission.\n(b) for the second conviction, the penalty of fine in the amount of not less than two thousand pesos (P2,000.00) but not exceeding five thousand pesos (5,000.00) at the discretion of the court.\n(c) for the third conviction, the penalty of fine in the amount of not less than five thousand pesos (P5,000.00) but not exceeding then thousand pesos (P10,000.00) and suspension of his license to practice his profession for thirty (30) days at the discretion of the court.\n(d) for the fourth and subsequent convictions, the penalty of fine of not less than ten thousand pesos (P10,000.00) and suspension of his license to practice his profession for one year or longer at the discretion of the court.\nB) Any juridical person who violates Section 6(c), 6(d), 7 or 8 shall suffer the penalty of a fine of not less than five thousand pesos (P5,000.00) nor more than ten thousand pesos (P10,000.00) and suspension or revocation of license to operate such drug establishment or drug outlet at the discretion of the Court: Provided,That its officers directly responsible for the violation shall suffer the penalty of fine and suspension or revocation of license to practice profession, if applicable, and by imprisonment of not less than six (6) months nor more than one (1) year or both fine and imprisonment at the discretion of the Court: and Provided, further, That if the guilty party is an alien, he shall be ipso facto deported after service of sentence without need of further proceedings. C) The Secretary of Health shall have the authority to impose administrative sanctions such as suspension or cancellation of license to operate or recommend suspension of license to practice profession to the Professional Regulation Commission as the case may be for the violation of this Act. Section 13. Separability Clause – If any provision of this Act is declared invalid, the remainder or any provision hereof not affected thereby shall remain in force and effect."}},{"id":"PH-H5172-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Repealing Clause – The provisions of any law, executive order, presidential decree or other issuances inconsistent with this Act are hereby repealed or modified accordingly."}},{"id":"PH-H5172-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Effectivity – This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or two (2) newspapers of general circulation."}}],"pack":"ph-p73"};
  FT["PH-H5173"] = {"id":"PH-H5173","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1988/ra_6676_1988.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Municipality of Mariano Marcos in the Province of Sultan Kudarat to Lambayong","orig":"An Act Changing the Name of the Municipality of Mariano Marcos in the Province of Sultan Kudarat to Lambayong"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6676","issuingBody":"Congress of the Philippines","promulgatedDate":"1988-10-17","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1988/ra_6676_1988.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5173-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Municipality of Mariano Marcos in the Province of Sultan Kudarat shall hereafter be known as the Municipality of Lambayong."}},{"id":"PH-H5173-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All laws or decrees inconsistent with any provision of this Act are hereby deemed amended accordingly."}},{"id":"PH-H5173-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p73"};
