  FT["PH-H5175"] = {"id":"PH-H5175","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1988/ra_6678_1988.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Municipality of San Mariano in the First District of the Province of Davao Del Norte to Municipality of Maragusan","orig":"An Act Changing the Name of the Municipality of San Mariano in the First District of the Province of Davao Del Norte to Municipality of Maragusan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6678","issuingBody":"Congress of the Philippines","promulgatedDate":"1988-10-12","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1988/ra_6678_1988.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5175-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Municipality of San Mariano in the first district of Davao del Norte shall hereafter be known as the Municipality of Maragusan."}},{"id":"PH-H5175-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All laws or decrees inconsistent with any provision of this Act are hereby deemed amended accordingly."}},{"id":"PH-H5175-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p73"};
  FT["PH-H5176"] = {"id":"PH-H5176","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1988/ra_6679_1988.html","fetchedAt":"2026-10-06","articleCount":19,"structureMode":"ARTICLE","title":{"zh":"对第 6653 号共和国法的修改","en":"An Act to Amend Republic Act No. 6653 to Postpone the Barangay Elections to March 28, 1989, Prescribing Additional Rules Governing the Conduct of Barangay Elections and for other purposes","orig":"An Act to Amend Republic Act No. 6653 to Postpone the Barangay Elections to March 28, 1989, Prescribing Additional Rules Governing the Conduct of Barangay Elections and for other purposes"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 6679","issuingBody":"Congress of the Philippines","promulgatedDate":"1988-11-04","completenessNote":"全文，共 19 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1988/ra_6679_1988.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5176-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The elections of barangay officials set on the second Monday of November 1988 by Republic Act No. 6653 are hereby postponed and reset to March 28, 1989. They shall serve a term which shall begin on the first day of May 1989 and ending on the thirty-first day of May 1994.\nThere shall be held a regular election of barangay officials on the second Monday of May 1994 and on the same day every five (5) years thereafter. Their term shall be for five (5) years which shall begin on the first day of June following the election and until their successors shall have been elected and qualified: provided, that no barangay official shall serve for more than three (3) successive terms.\nThe barangay elections shall be nonpartisan and shall be conducted in an expeditious and inexpensive manner."}},{"id":"PH-H5176-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"When for any serious cause such as rebellion, insurrection, violence, terrorism, loss or destruction of election paraphernalia, and any analogous causes of such nature that the holding of a free, orderly and honest election should become impossible in any barangay, the Commission on Elections motu propio or upon sworn petition of ten (10) registered voters of a barangay, after summary proceedings of the existence of such grounds, shall suspend or postpone the election therein to a date reasonably close to the date of the election that is not held or is suspended or postponed, or which resulted in a failure to elect, but not later than thirty (30) days after the cessation of the cause for such suspension or postponement of the election or failure to elect, and in all cases not later than ninety (90) days from the date of the original election."}},{"id":"PH-H5176-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The construction or maintenance of provincial, city, municipal and barangay-funded roads and bridges shall be prohibited for a period of ten (10) days immediately preceding the date of election, the provisions of Section 261, paragraphs (v) and (w), of the Omnibus Election Code to the contrary notwithstanding."}},{"id":"PH-H5176-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All incumbent barangay officials, whether elected, appointed or designated, shall remain in office unless sooner removed or suspended for cause and with due process by order of the city or municipal mayor concerned until their successors shall have been elected and qualified. Any barangay official who has been removed from office from January 1, 1988 to the date of the approval of this Act may, within fifteen (15) days after the effectivity of this Act, file a petition for review with the Office of the President which shall be decided within fifteen (15) days from receipt thereof: provided, that upon effectivity of this Act, the power of removal or suspension for cause of barangay officials and filling up of vacancies in the various elective offices of the barangay shall be exercised by the city or municipal mayor concerned, subject to appeal to the President: provided, further, that pending appeal the order of removal or suspension shall not be executory."}},{"id":"PH-H5176-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"There shall be a sangguniang barangay in every duly constituted barangay which shall be the legislative body and shall be composed of seven (7) kagawads to be elected by the registered voters of the barangay. The candidate who obtains the highest number of votes shall be the punong barangay and in the event of a tie, there shall be a drawing of lots under the supervision of the Commission on Elections. The chairman of the kabataang barangay who shall hereafter be elected in accordance with law shall be an ex officio member of the sangguniang barangay.n the event of any vacancy in the office of the punong barangay, whether temporary or permanent, or in case of disqualification or refusal to assume office, an order of succession among the six (6) members of the sangguniang barangay based upon the number of votes received from the highest to the lowest shall be followed to fill up the vacancy.n default of any duly elected member of the sangguniang barangay, the vacancy may be filled up by the city or municipal mayor concerned."}},{"id":"PH-H5176-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The official ballots for the barangay elections shall, before they are handed to the voters at the polling place, be authenticated by the chairman and the poll clerk who shall affix their signatures at the back thereof. Any ballot which is not authenticated shall be deemed spurious."}},{"id":"PH-H5176-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"No person shall be eligible for any barangay position unless he files a sworn certificate of candidacy with the election registrar of the city or municipality concerned at least ten (10) days immediately before the day of the election. The form and content of the certificate of candidacy shall be prescribed by the Commission on Elections. The campaign period shall be ten (10) days immediately before the election: provided, that no campaign shall be allowed on Holy Thursday and Good Friday for the barangay elections in 1989."}},{"id":"PH-H5176-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Incumbent elective officials running for the same office shall not be considered resigned upon the filing of their certificates of candidacy. They shall continue to hold office until successors shall have been elected and qualified."}},{"id":"PH-H5176-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"A sworn petition contesting the election of a barangay official may be filed with the proper municipal or metropolitan trial court by any candidate who has duly filed a certificate of candidacy and has been voted for a barangay office within ten (10) days after the proclamation of the results of the election. The trial court shall decide the election protest within thirty (30) days after the filing thereof. The decision of the municipal or metropolitan trial court may be appealed within ten (10) days from receipt of a copy thereof by the aggrieved party to the regional trial court which shall decide the issue within thirty (30) days from receipt of the appeal and whose decision on questions of fact shall be final and non- appealable. For purposes of the barangay elections, no pre-proclamation cases shall be allowed."}},{"id":"PH-H5176-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The Commission shall constitute, not later than ten (10) days immediately before the election, a board of election tellers in every barangay polling place, to be composed of three (3) public schoolteachers, one of whom shall be the chairman, provided they are not incumbent barangay officials or related within the fourth civil degree of affinity or consanguinity to any candidate for any position in that barangay.n case no public schoolteachers are available, the Commission shall designate any registered voter, preferably a regular government employee, in the polling place who is not an incumbent barangay official or related within the fourth civil degree of affinity or consanguinity to any candidate for any position in that barangay."}},{"id":"PH-H5176-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The Commission shall provide ballot boxes for each barangay polling place together with padlocks and other election paraphernalia."}},{"id":"PH-H5176-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Violations of the rules and regulations issued by the Commission are considered prohibited acts under the Omnibus Election Code and shall be prosecuted and penalized in accordance with the same Code."}},{"id":"PH-H5176-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"All candidates for barangay kagawad shall be required to file sworn post-election statements of expenditures and contributions as provided in Section 107 of the same Code."}},{"id":"PH-H5176-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"For purposes of the barangay elections, the election registrars of the Commission on Elections are authorized to administer oaths on all matters related to the conduct of said election."}},{"id":"PH-H5176-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"The amount of One hundred and fifty million pesos (P150,000,000.00) to defray the share of local government units in the expenses in connection with the conduct of these elections, to be disbursed by the Commission on Elections, is hereby authorized to be appropriated from the general fund of the Government not otherwise appropriated or from any savings therein, to be included in the General Appropriations Act for the Calendar Year 1989."}},{"id":"PH-H5176-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"The Omnibus Election Code shall as far as practicable be applicable to the barangay elections."}},{"id":"PH-H5176-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"If any part or provision of this Act is declared invalid or unconstitutional, the other parts or provisions thereof shall remain valid and effective."}},{"id":"PH-H5176-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"All laws, decrees, executive orders, letters of instruction, or any part thereof which may be inconsistent with this Act are hereby repealed or modified accordingly."}},{"id":"PH-H5176-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"This Act shall take effect upon its approval and publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p73"};
  FT["PH-H5177"] = {"id":"PH-H5177","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1988/ra_6680_1988.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Municipality of Linapacan, Province of Palawan, to Municipality of Gaudencio E. Abordo","orig":"An Act Changing the Name of the Municipality of Linapacan, Province of Palawan, to Municipality of Gaudencio E. Abordo"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6680","issuingBody":"Congress of the Philippines","promulgatedDate":"1988-11-04","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1988/ra_6680_1988.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5177-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Municipality of Linapacan, Province of Palawan, is hereby changed to Municipality of Gaudencio E. Abordo."}},{"id":"PH-H5177-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval by a majority of votes cast in a plebiscite to be conducted in accordance with law."}}],"pack":"ph-p73"};
  FT["PH-H5178"] = {"id":"PH-H5178","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1988/ra_6681_1988.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Municipality of Wright, Province of Samar, to Municipality of Paranas","orig":"An Act Changing the Name of the Municipality of Wright, Province of Samar, to Municipality of Paranas"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6681","issuingBody":"Congress of the Philippines","promulgatedDate":"1988-11-04","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1988/ra_6681_1988.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5178-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Municipality of Wright, Province of Samar, is hereby changed to Municipality of Paranas."}},{"id":"PH-H5178-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p73"};
  FT["PH-H5179"] = {"id":"PH-H5179","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1988/ra_6682_1988.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Amending the Effectivity Clause of Executive Order No. 292 Dated July 25, 1987","orig":"An Act Amending the Effectivity Clause of Executive Order No. 292 Dated July 25, 1987"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6682","issuingBody":"Congress of the Philippines","promulgatedDate":"1988-11-25","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1988/ra_6682_1988.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5179-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The effectivity clause provided in Section 29, Book VII, of Executive Order No. 292 dated July 25, 1987, known as the Administrative Code of 1987, is hereby amended to read as follows:\n\"Sec. 29. Effectivity. — This Code shall take effect two years after its publication in the Official Gazette.\""}},{"id":"PH-H5179-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect on November 24, 1988."}}],"pack":"ph-p73"};
  FT["PH-H5180"] = {"id":"PH-H5180","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1988/ra_6683_1988.html","fetchedAt":"2026-10-06","articleCount":17,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing Benefits for Early Retirement and Voluntary Separation from the Government Service, as well as Involuntary Separation of Civil Service Officers and Employees Pursuant to Various Executive Orders Authorizing Government Reorganization After the Ratification of the 1987 Constitution Appropriating Funds Therefore, and for other purposes","orig":"An Act Providing Benefits for Early Retirement and Voluntary Separation from the Government Service, as well as Involuntary Separation of Civil Service Officers and Employees Pursuant to Various Executive Orders Authorizing Government Reorganization After the Ratification of the 1987 Constitution Appropriating Funds Therefore, and for other purposes"},"level":"law","status":"active","topics":["labor","administrative"],"docNumber":"Republic Act No. 6683","issuingBody":"Congress of the Philippines","promulgatedDate":"1988-12-02","completenessNote":"全文，共 17 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1988/ra_6683_1988.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5180-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of Policy. - It is hereby declared the policy of the State to promote economy, efficiency and effectiveness in government operations, particularly in the delivery of essential public services. For this purpose, the State shall endeavor to streamline government functions and to maintain necessary positions through an appropriate retirement and voluntary separation scheme."}},{"id":"PH-H5180-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Coverage. - This Act shall cover all appointive officials and employees of the National Government, including government-owned or controlled corporations with original charters, as well as the personnel of all local government units. The benefits authorized under this Act shall apply to all regular, temporary, casual and emergency employees, regardless of age, who have rendered at least a total of two (2) consecutive years of government service as of the date of separation. Uniformed personnel of the Armed Forces of the Philippines including those of the PC-INP are excluded from the coverage of this Act."}},{"id":"PH-H5180-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Early Retirement and Voluntary Separation Benefits. - All appointive government officials and employees included in the coverage hereof who voluntarily elect in writing to be retired or separated from the service and whose retirement has been approved under the provisions of this Act shall be paid retirement or separation benefits equivalent to one and one-fourth (1 1/4) month basic salary for every year of their respective government services or the nearest equivalent fraction thereof favorable to them on the basis of the highest salary which they respectively received in the course of their employment in the government: provided, that in no case shall the benefit to be paid to any appointive official or employee be less than Ten thousand pesos (P10,000): provided, further, that any appointive official or employee who has previously been found guilty in an administrative proceeding and whose rank or salary has been reduced shall be paid on the basis of his last salary."}},{"id":"PH-H5180-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Additional Benefits. - In addition to the benefits herein authorized, covered appointive officials and employees who retire or voluntarily elect to be separated from the service under this Act shall be entitled to the return of GSIS personal contributions pertaining to retirement only and the payment of the corresponding share of the government with interest earned pursuant to existing rules and regulations of the Government Service Insurance System. They shall likewise be entitled to the commutation of unused vacation and sick leaves in accordance with existing rules and regulations: provided, however, that should the government agency concerned lack the necessary funds for this, the same shall come from the appropriation to fund this Act: provided, further, that those who retire after rendering government service for thirty-one (31) years or more and avail themselves of the incentive benefits provided under this Act shall be entitled to an additional ten percent (10%) of the amount corresponding to what they will receive from the thirty-first year onward."}},{"id":"PH-H5180-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Exclusiveness of Benefits. - An appointive official or employee who retires or elects to be separated from the service under this Act shall not be eligible for optional retirement with gratuity under Republic Act Nos. 1616 and 4968 or with pension under Commonwealth Act. No. 186, as amended by Republic Act No. 660, or under Presidential Decree No. 1146, as amended, or vice-versa."}},{"id":"PH-H5180-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Abolition of Positions. - The positions vacated through the early retirement or separation of its incumbent shall be abolished unless the head of the office or agency, with the approval of the President in the case of the Executive Department, the Chief Justice in the case of the Judiciary, the Senate President or the Speaker of the House of Representatives in the case of Congress, the Chairman in the case of the Constitutional Commissions, certifies within the period of sixty (60) days from the time of approval or acceptance of the application for retirement or separation that the exigencies of the service require its retention."}},{"id":"PH-H5180-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Discretion of Agency Heads in Acceptance of Application for Early Retirement and Voluntary Separation. - No appointive official or employee shall be separated or retired under this Act unless his application for early retirement or voluntary separation shall have been accepted by the head of the government office or agency or by the chief executive officer of the government-owned or controlled corporation concerned as the case may be.\nFor purposes of this Act, \"head of government office or agency\" refers to the Secretary in the case of bureaus, divisions and other offices under a department; governor or mayor, as the case may be, in the case of local government units; the Chief of Justice in the case of the employees of the Judiciary; the Senate President or the Speaker of the House of Representatives, as the case may be, in the case of employees of the Legislature; the Chairman in the case of the Constitutional Commissions; and in the case of other offices not within the authority of those previously mentioned, their overall superior.\nThe application for early retirement or voluntary separation shall be accepted unless the services of the applicant shall be deemed necessary. The application of those with pending administrative cases punishable by dismissal or removal shall be held in abeyance until the final disposition of such cases without prejudice to their receiving benefits under this law in case of acquittal.\nThe applications of those with criminal cases of grave nature committed in relation to their office shall be held in abeyance."}},{"id":"PH-H5180-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Restriction on the Employment and Replacement of Retired or Separated Personnel. - Appointive officials and employees who are retired or separated under this Act shall not be eligible for appointment to, or employment in any branch, division, instrumentality or agency of the government, including government-owned or controlled corporations with original charters whether on a permanent, temporary, casual or emergency status within a period of five (5) years after separation unless they refund the benefits they received: provided, however, that those reemployed in the government shall be treated as new entrants insofar as GSIS coverage is concerned.\nPositions vacated but retained shall be filled by personnel chosen from among the most deserving employees in the agency concerned or from any other agency."}},{"id":"PH-H5180-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Period of Applicability and Effectivity of the Incentive Benefits. - Applications for early retirement and voluntary separation benefits hereunder shall be entertained only if filed within a period of two (2) months from the issuance of the rules and regulations for the implementation of this Act pursuant to Section 13 hereof. The oldest employees who are the most senior in the service will be given priority in the payment of benefits."}},{"id":"PH-H5180-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Funding. - For national government employees, the sum of Three billion pesos, or so much thereof as may be necessary, is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated for payment of early retirement and separation incentive benefits authorized in this Act.\nFor employees of government-owned or controlled corporations, the benefits herein granted shall be paid from the internal funds of the respective corporations.n no case shall the benefits paid to employees of government-owned or controlled corporations be less than the benefits granted by their existing corporate programs, if any.\nFor employees of local government units, the benefits shall be paid from available funds of each local government unit.\nGovernment-owned or controlled corporations and local government units which may not be able to adequately fund the incentive benefits under this Act may avail themselves of the Three billion peso fund appropriation for this purpose but only to the extent of twenty-five percent (25%) of the requirements on the condition that their plantilla and staffing pattern shall, for a period of one (1) year from the effectivity of this Act, be subject to approval of the Department of Budget and Management: provided, that in the case of government-owned or controlled corporations, said twenty-five percent (25%) may be deducted by the Department of Budget and Management from whatever budgetary allocation and assistance they may get from the National Government in the future.\nThe above provisions notwithstanding, all savings accruing from the abolition of positions pursuant hereto shall be earmarked and used exclusively for the payment of the benefits under this Act."}},{"id":"PH-H5180-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Retroactive Charges. - Officials and employees who were previously separated from the government service not for cause but as a result of the reorganization pursuant to various executive orders authorizing government reorganization issued after the ratification of the 1987 Constitution shall be deemed covered and entitled to avail of the incentive benefits under this Act."}},{"id":"PH-H5180-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Penalties. - Any government official who compels an employee under any guise whatsoever to retire or be separated from government service by virtue of this Act or otherwise violates provisions hereof shall, upon conviction, be punished by a fine not exceeding One thousand pesos (P1,000), or by imprisonment not exceeding six (6) months or both such fine and imprisonment in the discretion of the court."}},{"id":"PH-H5180-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Implementing Rules and Regulations. - The implementing rules and regulations shall be issued within fifteen (15) days from the date of effectivity of this Act by the Department of Budget and Management, in consultation with the Civil Service Commission: provided, that any provision of law to the contrary notwithstanding, the only documents or supporting papers to be submitted by appointive officials and employees who wish to avail themselves of the benefits under this Act are the following:\n(a) A duly approved application under oath for early retirement or voluntary separation in accordance with this Act, including a statement of the number of years of service in the government and the rate of the highest salary received.\n(b) Money and property clearance from the agency concerned where proper pursuant to Section 7 hereof; and\n(c) A simplified statement of assets and liabilities, net worth, and financial and business interests in the case of regular employees: provided, further, that the processing and actual payment of benefits to the appointive officials and employees concerned shall be completed within fifteen (15) days from the date of submission of all the foregoing documents."}},{"id":"PH-H5180-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Compliance and Reporting. - Six (6) months from the effectivity of this Act, the Department of Budget and Management and the Civil Service Commission shall, on the basis of the reports of the various heads of government offices and agencies, render a report to Congress on the number of government employees affected, the type or nature of positions involved, the total amount spent and an evaluation thereof."}},{"id":"PH-H5180-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Repealing Clause. - All laws, rules and regulations or parts thereof, inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H5180-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Separability Clause. - If any part, section or provision of this Act shall be held invalid or unconstitutional, no other part section or provision thereof shall be affected thereby."}},{"id":"PH-H5180-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Effectivity. - This Act shall take effect upon publication in two (2) newspapers of general circulation."}}],"pack":"ph-p73"};
  FT["PH-H5181"] = {"id":"PH-H5181","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1988/ra_6684_1988.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Municipality of Don Mariano Marcos, Province of Zamboanga Del Sur, to Municipality of Sominot","orig":"An Act Changing the Name of the Municipality of Don Mariano Marcos, Province of Zamboanga Del Sur, to Municipality of Sominot"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6684","issuingBody":"Congress of the Philippines","promulgatedDate":"1988-12-04","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1988/ra_6684_1988.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5181-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the municipality of Don Mariano Marcos, Province of Zamboanga del Sur, is hereby changed to Municipality of Sominot."}},{"id":"PH-H5181-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p73"};
  FT["PH-H5182"] = {"id":"PH-H5182","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1988/ra_6685_1988.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Requiring Private Contractors to Whom National, Provincial, City and Municipal Public Works Projects Have Been Awarded Under Contract to Hire at Least Fifty Percent of the Unskilled and at Least Thirty Percent of the Skilled Labor Requirements to Be Taken From the Available Bona Fide Residents in the Province, City or Municipality in Which the Projects Are to Be Undertaken, and Penalizing Those Who Fail to Do So","orig":"An Act Requiring Private Contractors to Whom National, Provincial, City and Municipal Public Works Projects Have Been Awarded Under Contract to Hire at Least Fifty Percent of the Unskilled and at Least Thirty Percent of the Skilled Labor Requirements to Be Taken From the Available Bona Fide Residents in the Province, City or Municipality in Which the Projects Are to Be Undertaken, and Penalizing Those Who Fail to Do So"},"level":"law","status":"active","topics":["criminal"],"docNumber":"Republic Act No. 6685","issuingBody":"Congress of the Philippines","promulgatedDate":"1988-12-12","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1988/ra_6685_1988.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5182-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Contractor Requirement. - All private contractors, including subcontractors, to whom awards are made for the undertaking of national and local public works projects funded by either the National Government or any local government unit including foreign-assisted projects must hire at least fifty percent (50%) of the unskilled and thirty percent (30%) of the skilled labor requirements from the unemployed bona fide and actual residents in the province, city and municipality who are ready, willing and able as determined by the governor, city mayor or municipal mayor concerned where the projects are to be undertaken: provided, that labor used or to be used for the manufacture of prefabricated construction materials and other materials premade outside the place of project implementation and skilled manpower utilized or to be utilized for the preparation of engineering designs and project plans and layouts shall be exempted from the labor requirements herein imposed: provided, further, that where the number of available resources is less than the required percentages provided herein, said requirements shall be based on the maximum number of locally available labor resources which fact shall be certified by the municipal, city, provincial or district engineer as sufficient compliance with the labor requirements under this Act."}},{"id":"PH-H5182-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Public Works Projects Involved. - Public works projects referred to include national, provincial, city, municipal, and barangay projects including but not limited to roads, schools, power and water systems, piers, airports and similar projects."}},{"id":"PH-H5182-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Excluded Projects. - Any scientific project of a highly technical nature, all defense and military installations which fall under security requirements, any public works project that may be assigned to and which can be undertaken by the engineering battalions of the Armed Forces of the Philippines shall be excluded: provided, that where such strategic projects are to be undertaken by private contractors, the same shall require the clearance and permission of the Chief of Staff of the Armed Forces of the Philippines and/or the Secretary of the Department of Science and Technology, and the provisions of Section 1 shall apply."}},{"id":"PH-H5182-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Notice of Labor Requirements. - The contractor and/or subcontractor shall post in conspicuous areas to be specified and designated by proper district, provincial, city or municipal authorities, a notice in either Filipino, English or the local dialect, that local residents are needed for the project. Applicants shall bring their voter's identification card or any reliable document of identification or submit a verification from the barangay captain or any other member of the barangay council in the absence of the barangay captain to prove that they are bona fide and actual residents of the locality where the project will be undertaken. Furthermore, applicants shall pass reasonable performance requirements of the contractor."}},{"id":"PH-H5182-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Certificate of Compliance. - The contractor and/or subcontractor shall submit to the district, provincial or city engineer, among the requirements for every progress billing, a certificate of compliance with the above requirements duly sworn to, including a list of names of residents hired from the locality where the project was undertaken."}},{"id":"PH-H5182-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Penalty. - Failure without good cause by the contractor or subcontractor to comply with the requirements of Sections 1, 4 and 5 of this Act shall be penalized by a fine of Twenty thousand pesos (P20,000) for the first offense; suspension for one (1) year from participating in public works bidding for the second offense; and perpetual disqualification from participating in public works bidding for the third offense. The penalty clause as provided for in this Act shall be included in all contracts to be entered into by and between the national, provincial, city and municipal governments and the contractor upon approval of this Act."}},{"id":"PH-H5182-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Rules and Regulations. - The Secretary of the Department of Public Works and Highways (DPWH) shall, after consultation with duly accredited national constructors associations and the Secretary of Labor, issue implementing rules and regulations within sixty (60) days upon approval of this Act."}},{"id":"PH-H5182-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Effectivity. - This Act shall take effect upon its complete publication in at least two (2) national newspapers of general circulation."}}],"pack":"ph-p73"};
  FT["PH-H5183"] = {"id":"PH-H5183","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1988/ra_6686_1988.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Authorizing Annual Christmas Bonus to National and Local Government Officials and Employees Starting CY 1988","orig":"An Act Authorizing Annual Christmas Bonus to National and Local Government Officials and Employees Starting CY 1988"},"level":"law","status":"active","topics":["labor","administrative"],"docNumber":"Republic Act No. 6686","issuingBody":"Congress of the Philippines","promulgatedDate":"1988-12-14","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1988/ra_6686_1988.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5183-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"All officials and employees of the National Government who have rendered at least four months of service from January 1 to October 31 of each year and who are employed in the government service as of October 31 of the same year shall each receive a Christmas bonus equivalent to one month basic salary and additional cash gift of One thousand pesos (P1,000)."}},{"id":"PH-H5183-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Officials and employees of the National Government who have rendered less than four months of service from January 1 to October 31 of each year and who are employed in the government service as of October 31 of the same year shall be entitled solely to the following cash gift:\nLength of Service\nAmount 3 months but less than 4 months P400.00 2 months but less than 3 months\n300.00 1 month but less than 2 months\n200.00 Less than one month\n100.00"}},{"id":"PH-H5183-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"For CY 1988, the amount needed to implement this Act for national officials and employees, and barangay chairmen under Section 5 hereof, shall be taken from appropriations under the Compensation and Organizational Adjustments Fund and the Government Employees Amelioration Fund. Any deficiency shall be taken from savings in appropriations authorized under Republic Act No. 6642, the General Appropriations Act for 1988. For the succeeding years, the amount shall be included in the annual General Appropriations Act."}},{"id":"PH-H5183-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All officials and employees of local government units may receive the same benefits as are provided under Sections 1 and 2 of this Act chargeable against their respective local funds. For CY 1988, local government units (municipalities, cities and provinces) may realign their budgets including released NALGU Funds to give priority to the funding requirements under this Act and any deficiency may be booked as accounts payable to be paid on a first priority basis in succeeding years."}},{"id":"PH-H5183-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Barangay chairmen shall each receive a cash gift of One thousand pesos (P1,000) payable out of the funds provided for in Section 3 hereof."}},{"id":"PH-H5183-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"No official or employee shall receive Christmas bonus from any and all sources in excess of the one month basic salary and One thousand pesos (P1,000) cash gift."}},{"id":"PH-H5183-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The Department of Budget and Management shall issue the implementing rules and regulations to carry out the provisions of this Act."}},{"id":"PH-H5183-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p73"};
  FT["PH-H5184"] = {"id":"PH-H5184","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1988/ra_6687_1988.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Municipality of Potia, Province of Ifugao, into Lista and Confirming the Barangay of Sta. Maria, Municipality of Lista, Province of Ifugao, as the Seat of the Government of the Municipality of Lista","orig":"An Act Changing the Name of the Municipality of Potia, Province of Ifugao, into Lista and Confirming the Barangay of Sta. Maria, Municipality of Lista, Province of Ifugao, as the Seat of the Government of the Municipality of Lista"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 6687","issuingBody":"Congress of the Philippines","promulgatedDate":"1988-12-15","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1988/ra_6687_1988.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5184-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Municipality of Potia is hereby changed to the Municipality of Lista."}},{"id":"PH-H5184-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The present seat of the municipal government in the Barangay of Sta. Maria, Municipality of Lista, Province of Ifugao is hereby confirmed as the seat of the government of the Municipality of Lista."}},{"id":"PH-H5184-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval and its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p73"};
  FT["PH-H5185"] = {"id":"PH-H5185","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1988/ra_6688_1988.html","fetchedAt":"2026-10-06","articleCount":56,"structureMode":"ARTICLE","title":{"zh":"政府运营经费拨款法","en":"An Act Appropriating Funds for the Operation of the Government of the Republic of the Philippines From January One to December Thirty-One, Nineteen Hundred and Eighty-Nine, and for Other Purposes","orig":"An Act Appropriating Funds for the Operation of the Government of the Republic of the Philippines From January One to December Thirty-One, Nineteen Hundred and Eighty-Nine, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6688","issuingBody":"Congress of the Philippines","promulgatedDate":"1988-12-29","completenessNote":"全文，共 56 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1988/ra_6688_1988.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 57 条，缺 11）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5185-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Appropriation Funds. - The following sums, or so much thereof as may be necessary, are hereby appropriated out of any funds in the National Treasury of the Philippines not otherwise appropriated, for the Operation of the Government of the Republic of the Philippines from January one to December thirty-one, nineteen hundred and eighty-nine except where otherwise specifically provided herein:\nI. Congress of the Philippines\nII. Office of the President\nIII. Office of the Vice President\nIV. Department of Agrarian Reform\nV. Department of Agriculture\nVI. Department of Budget and Management\nVII. Department of Education, Culture and Sports\nVIII. State Universities and Colleges\nIX. Department of Environment and Natural Resources\nX. Department of Finance\nXI. Department of Foreign Affairs\nXII. Department of Health\nXIII. Department of Justice\nXIV. Department of Labor Employment\nXV. Department of Local Government\nXVI. Department of National Defense\nXVII. Department of Public Works and Highways\nXVIII. Department of Science and Technology\nXIX. Department of Social Welfare and Development\nXX. Department of Tourism\nXXI. Department of Trade of Industry\nXXII. Department of Transportation and Communications\nXXIII. National Economic and Developement Authority\nXXIV. Other Executive Offices\nXXV. The Judiciary\nXXVI. Constitutional Offices\nXXVII. Office of the Ombudsman\nXXVIII. Office of the Special Prosecutor\nXXIX. Commission on Human Rights\nXXX. Autonomous Regions\nXXXI. Budgetary Support to Government Corporations\nXXXII. National Assistance to Local Government Units\nXXXIII. Calamity Fund\nXXXIV. Contingent Fund\nXXXV. Economic Support Fund\nXXXVI. Foreign-Assisted Projects Support Fund\nXXXVII. Mindanao Development Fund\nXXXVIII. Visayas Development Fund\nXXXIX. Miscellaneous Public Works Fund\nXL. General Fund Adjustments\nXLI. Property Replacement Fund\nXLII. Inter-Regional Development Fund\nXLIII. Unprogrammed Fund\nGENERAL PROVISION"}},{"id":"PH-H5185-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Fees, Charges and assessments. All fees, charges, assessments, and other receipts or revenues collected by departments, bureaus, offices or agencies in the exercise of their functions, at such rates as are now or may be approved by the Secretary concerned, shall be deposited with the National Treasury and shall accrue to the General Fund pursuant to Section 50 of P.D. No. 1177 and Section 3 of B.P. Blg. 325: PROVIDED, That certain receipts may be recorded as income of a Special Fund, a Fiduciary or a Trust Fund, or a fund other than the General Fund, when authorized by law and following such rules and regulations as may be issued by the Permanent Committee created under Section 51 of P.D. No. 1177: PROVIDED, FURTPER, That all revenues or income accruing to special accounts in the General Fund may be made available for expenditure, subject to the Special Provision in this Act for the agencies concerned and to Special Budgets required under Section 40 of P.D. No. 1177: AND PROVIDED, FURTHERMORE, That whenever practicable and taking into account the cost reduction program of the government, when an agency contracts with another government office for fabrication of furniture or equipment, or for computer, printing or other services, the agency rendering such services may assess the requesting agency for the cost of production and services rendered and may utilize the proceeds thereof subject to Section 40 of P.D. No. 1177, except as otherwise provided in this Act: AND PROVIDED, FINALLY, That the schedule of fees, charges and assessments collectible by any government agency including government-owned and/or controlled corporations, shall be posted in big bold characters in a conspicuous place in said government agency or corporations including its branches or extension offices and that the updating and continuous display of said schedule shall be the responsibility of the head of the agency or corporation concerned."}},{"id":"PH-H5185-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Revolving Fund. Revolving funds shall be established and maintained only in cases where said funds are expressly created and authorized by law. Revolving fund already in existence shall continue their operations.\nReceipts derived from business type activities of departments, bureaus, offices or agencies which are authorized by law to be constituted into a Revolving Fund shall be separately recorded and deposited in an authorized government depository bank, and may be made available for operational expenses of the said activity of the agency concerned, subject to the conditions prescribed under the special provision of the agency concerned and the rules and regulations as may be prescribed by the aforementioned Permanent Committee. The Revolving Fund shall be considered self-perpetuating and self-liquidating and all obligations or expenditures incurred by virtue of said business-type activities shall be charged against the Revolving Fund: PROVIDED, That interest and other income earned shall be deposited with the National Treasury and shall accrue to the General Fund pursuant to Section 65 of P.D. No. 1445 and Section 29 (1) of Article VI of the Constitution.\nThe agency concerned shall submit to the Department of Budget and Management a monthly report of the income from this Fund and a quarterly report of expenditure. In case of failure to submit said requirements, the Department of Budget and Management shall order the suspension of all transactions on this account until such time when said requirements are complied with."}},{"id":"PH-H5185-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Trust Receipts. Receipts from non-tax sources authorized by law for specific purposes which are collected/received by a government office or agency acting as a trustee, agent or administrator, or which have been received as guaranty for the fulfillment of an obligation, and all other collections classified by law or regulations as trust receipts shall be treated as a trust liability of the agency concerned and deposited in an authorized government depository bank or in the National Treasury, as the case may be, subject to the conditions prescribed under the Special Provisions of the agency concerned and to the rules and regulations as determined by the Permanent Committee created under Section 51 of P.D. No. 1177. Payment out of such funds shall be made in accordance with the purpose for which the fund is created and subject to accounting and auditing regulations: PROVIDED, That deposits in authorized government depository banks shall be withdrawable, subject to existing budget, accounting and auditing rules and regulations without the need for the issuance of a Funding Warrant: PROVIDED, FURTHER, That if the amount is deposited in a savings account, the interest shall accrue to the General Fund and shall be remitted to the National Treasury at the end of each quarter."}},{"id":"PH-H5185-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Seminar and Conference Fees. Departments, bureaus, offices or agencies which conduct training programs approved jointly by the Department of Budget and Management and the Civil Service Commission are authorized to collect seminar and conference fees from government and private agency participants, at such standard rates as the Department of Budget and Management and the Civil Service Commission shall deem appropriate. The proceeds derived from such seminars or conferences may be made available for the conduct of such seminars and conferences, subject to pertinent budget, accounting and auditing rules and regulations: PROVIDED, That any excess therefrom shall be remitted to the National Treasury: PROVIDED, FURTHER, That upon the conclusion of the seminar or conference, the office authorized to conduct the same shall submit to the Department of Budget and Management a report of the income realized and of the expenses incurred: PROVIDED, FINALLY, That no appropriation authorized in this Act shall be used to support or augment expenses of seminars or conferences."}},{"id":"PH-H5185-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Sale of Products. Departments, bureaus, offices or agencies are authorized to sell products of agricultural industrial or other projects, including official publications. The proceeds derived therefrom shall be deposited with the National Treasury and shall accrue to the General Fund, pursuant to Section 50 of P.D. No. 1177, unless otherwise provided by law or authorized by Special Provision in this Act."}},{"id":"PH-H5185-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Donations. Departments, bureaus, offices or agencies are authorized to accept donations, contributions, grants, bequests or gifts, in cash or in kind, from foreign governments, international and local agencies, private entities or individuals for purposes relevant to their functions. Such receipts shall be recorded in the books of the government and shall be subject to pertinent accounting and auditing rules and regulations. Such donations, whether in cash or in kind, shall be deemed automatically appropriated for the purposes specified by the donor. Cash proceeds shall be deposited with the National Treasury as Special Account in the General Fund and shall be released only to the extent of actual receipts as certified by the Bureau of the Treasury and used or expended as specified by the donor, subject to Section AO of P.D. No. 1177. The agency concerned shall submit to the Department of Budget and Management and to the Commission on Audit a quarterly report of the expenditures or disbursements of the amounts released. Whenever a donation is made, the recipient office or agency shall notify the Department of Budget and Management which shall issue the corresponding advice of allotment."}},{"id":"PH-H5185-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Grants-in-Aid Donations and Contributions to Private Non-Profit, Socio-Civic, and Charitable Institutions and Organizations. Pursuant to the State policy of encouraging the participation of the private sector, and subject to the approval of their respective department secretaries, government agencies are authorized to provide grants-in-aid to socio-civic, non-profit and other non-government organization for operation and activities that are in line with services rendered by the government, and within the mandate of the respective government agencies, whenever it is impractical or more expensive for the government to directly undertake such operations and activities, subject to accounting and auditing rules and regulations."}},{"id":"PH-H5185-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Performance Bonds and Deposits. Performance bonds and deposits filed or posted by private persons or entities with agencies of the government shall be deposited with an authorized government depository bank as trust liabilities and under the name of the agency concerned. Upon faithful performance of the undertaking or termination of the obligation for which the bond or deposit was required, any amount due shall be returned to the filing party and the office or agency concerned, withdrawable in accordance with accounting and auditing rules and regulations: PROVIDED, That any interest accruing on deposit accounts and any forfeited amounts shall be recorded as income of the General Fund and shall be remitted to the National Treasury at the end of each quarter- This provision shall apply to bonds posted in cash, such as bidder's bond, guaranty bonds, bail bonds, judicial deposits for the benefit of clients, cash under litigation deposited in court or quasi-judicial bodies and other refundable and judicial bonds, and all bonds and deposits required by law, rules and regulations to be posted to ensure the faithful performance of an activity or undertaking.\nAUTHORIZED EXPENDITURES"}},{"id":"PH-H5185-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Restrictions on the Use of Appropriated Funds. The amounts released, particularly for hut not limited to, petroleum, oil and lubricants as well as for water, illumination and power services, telephone and other communication services, rents, retirement gratuity and terminal leave requirements shall be disbursed solely for such items of expenditures in accordance with the Work and Financial Plan as approved by the Secretary of Budget and Management.\nThe use of funds in violation of this Section shall be null and void, and shall subject the erring officials and employees to disciplinary action under the provisions of Sections 49 and 87 of P.D. No. 1177 and to appropriate criminal action under existing penal laws. Sec. 11. Expenditure Components. Except by act of the Congress of the Philippines, no change or modification shall be made in the expenditure items authorized in this Act and other appropriations laws unless in cases of augmentations from savings in appropriations as authorized under Section 25 (5) of Article VI of the Constitution."}},{"id":"PH-H5185-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Use of Savings. The President, the President of the Senate, the Speaker of the House of Representatives, the Chief Justice of the Supreme Court, the Heads of the Constitutional Commissions, and the Ombudsman are hereby authorized to augment any item in this Act for their respective offices from savings in other items of their respective appropriations."}},{"id":"PH-H5185-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Expenditures Funded from Borrowings. The amounts appropriated in this Act and funded from local or foreign borrowings shall be released in accordance with loan drawdowns or in the manner stipulated in the financing agreement concerned, subject to Section 40 of P.D. No. 1177."}},{"id":"PH-H5185-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Information Outlay. The appropriations pertaining to information activities of various departments, bureaus, offices or agencies shall be released upon presentation of an appropriate program of activities prepared by their respective heads, copies of which shall be furnished the Congress of the Philippines."}},{"id":"PH-H5185-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Foreign Purchases and Other Importations. Purchases under foreign military sales agreements, heavy equipment imports for infrastructure projects and other importations of agencies which are financed by foreign borrowings or by Central Bank consolidated borrowing programs shall be subject to the requirement of a certification of availability of appropriations released for the purpose, to the requirements of LOI No. 880 and to applicable laws, rules and regulations."}},{"id":"PH-H5185-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Purchase of Supplies, Materials and Equipment Spare Parts. The stock on hand of supplies, materials and equipment spare parts to be acquired through ordinary purchase out of appropriations herein provided shall at no time exceed normal three-month requirements, subject to pertinent rules and regulations issued by competent authority: PROVIDED, That heads of departments, bureaus, offices or agencies or other instrumentalities of the government may approve the build-up of stocks on hand of critical supplies and materials as defined or specified by the Department of Budget and Management in anticipation of cost increases, of requirement of a national emergency, or of an impending shortage in the items concerned, specifying maximum quantities of individual items. In no case, however, shall these stocks exceed more than one year's need, unless otherwise approved by the President of the Philippines, upon the joint recommendation of the Secretary concerned and the Chairman of the Commission on Audit."}},{"id":"PH-H5185-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Emergency Purchases. Unless otherwise provided in this Act, departments, bureaus, offices or agencies of the national government are authorized to make emergency purchases of supplies, materials and spare parts of motor transport equipment that are urgently needed for the repair of ambulances, motor vehicles, vessels and aircrafts or to meet an emergency which may involve the loss of, or danger to, life and/or property, or are to be used in connection with a project or activity which cannot be delayed without causing detriment to the public service, in a monthly amc»jr.t not exceeding four percent of the annual agency expenditure program for supplies and materials out of the appropriations allotted for maintenance and other operating expenses of the agency concerned, except as may be authorized by the President of the Philippines upon the joint recommendation of the Department of Budget and Management and the Commission on Audit."}},{"id":"PH-H5185-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Cultural and Athletic Activities. An amount not exceeding P45,000 per annum out of the appropriations allotted for maintenance and other operating expenses for each department, bureau, office or agency, and P15,000 for each regional office of each regionalized department, bureau, office or agency, may be used for cultural and athletic activities, including purchase of uniforms at not more than P500 for each participant, and for supplies and necessary expenses for said activities. The amounts fixed in this Section constitute the allowable maximum to be expended by any department, bureau, office or agency for its cultural and athletic activities, except as otherwise approved by the President of the Philippines; PROVIDED That, these amounts may be pealed by the Secretary concerned into one fund, programmed and controlled to best serve the needs of the department and all the offices, bureau and agencies therein. For purposes of this Section, the term \"office or agency\" shall be so construed to refer only to departments and bureaus, and the regular government offices or agencies under them."}},{"id":"PH-H5185-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Extraordinary and Miscellaneous Expenses. Appropriations herein authorized may be used for extraordinary expenses not exceeding:\na. P120,000 for each Secretary or equivalent;\nb. P40,000 for each Undersecretary or equivalent;\nc. P16,000 for each Assistant Secretary, head of bureau or organization of equal rank to bureau and for each Department Regional Director; and\nd. P8,000 for each Bureau Regional Director.\nIn addition, miscellaneous expenses not exceeding P24,000 for each of the offices under the above-named officials are herein authorized.\nFor purposes of this Section, extraordinary and miscellaneous expenses shall not be limited to, expenses incurred for; include, but\na. meetings, seminars and conferences;\nb. official entertainment;\nc. public relations;\nd. educational, athletic and cultural activities;\ne. contributions to civic or charitable institutions;\nf. membership in government associations;\ng. membership in national professional organizations duly accredited by the Professional Regulation Commission;\nh. membership in the Integrated Bar of the Philippines;\ni. subscription to professional technical journals and informative magazines, library books and materials; office equipment and supplies; and\nk. other similar expenses not supported by the regular budget allocation. No portion of the amounts authorized herein shall be used for salaries, wages, allowances, intelligence and confidential expenses.\nThese expenditures shall be subject to the accounting and auditing rules and regulations."}},{"id":"PH-H5185-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Release of Intelligence and Confidential Funds. No amount appropriated in this Act shall be released or disbursed for confidential and intelligence activities unless specifically identified and authorized as such intelligence or confidential fund in this Act. Intelligence and confidential funds provided for in the budgets of departments, bureaus, offices or agencies of the national government, including amounts from savings authorized by Special Provisions to be used for intelligence and counter-intelligence activities, shall be released only upon approval of the President of the Philippines. All departments, bureaus and offices shall submit to the Secretary of the Department of Budget and Management, the Chairman of the House Committee on Appropriations and the Chairman of the Senate Committee on Finance, a quarterly report on the utilization of intelligence and confidential funds."}},{"id":"PH-H5185-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Release of Funds. Any provision of law to the contrary notwithstanding, the appropriations authorized for the Judiciary, Congress, the Commission on Human Rights, the Office of the Ombudsman, the Civil Service Commission, the Commission on Audit and the Commission on Elections in this Act shall be automatically and regularly released in accordance with a Work and Financial Plan."}},{"id":"PH-H5185-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Funding of Contracts and Future Payment of Contractual Obligations. Notwithstanding the availability of deferred payment terms, departments, bureaus, offices or agencies concerned, before entering into contracts involving tine expenditure of public funds, including contracts for services or consultancy, contracts of lease, equipment rental, construction of partitions or improvements in leased buildings, or contracts involving an increase in the approved contract price shall secure a certification of availability of funds for the purpose from the agency Chief Accountant, subject to applicable rules and regulations as may be issued by the Department of Budget and Management and to Sections 46 and 64 of P.D. No. 1177: PROVIDED, That the certification of availability of funds sufficient to cover the cost of the contracted activities shall be contained in and made part of the contract duly signed by the Chief Accountant of the contracting agency, as provided for by LOI No. 968. Departments, bureaus, offices or agencies, before entering into contracts for delivery of goods or services against future payment, shall likewise first secure a certification of the availability of the full contracted amount for such goods or services out of the agency's appropriations. No contracts shall be entered into nor work undertaken without such certification of fund availability."}},{"id":"PH-H5185-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Loan Agreements. Departments, bureaus, offices or agencies, including government-owned and/or controlled corporations shall in no case enter into foreign or domestic loan agreements, whether in cash or in kind, except upon concurrence of the Secretary of Budget and Management with respect to peso requirements and implications on expenditure ceilings and prior approval of the President of the Philippines, with the prior concurrence of the Monetary Board, subject to such limitations as may be provided by law: PROVIDED, That the Monetary Board shall, within thirty days from the end of every quarter of the calendar year, submit to Congress a report of its decisions on applications for loans to be contracted or guaranteed by the government or government-owned and/or controlled corporations which have the effect of increasing the foreign debt. Loans shall not be contracted by agencies of the national government unless the full amount of the loan is covered by an Obligational Authority issued by the Secretary of Budget and Management.\nFor this purpose, the budgetary implications of foreign-assisted projects shall be explicitly considered by the Secretary of Budget and Management and the office or agency concerned at the time of project design and financing negotiations. The project study shall specify the cash flow requirements of the project among others, for: (a) payment of principal and interest; (b) peso component of capital costs and project preparation (c) infrastructure and support facilities needed to be directly financed by government; (d) operating and other expenditures which will be ultimately required for general fund support when the project is implemented; and (e) peso requirements needed as counterpart."}},{"id":"PH-H5185-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Service Contracts. Departments, bureaus, offices or agencies are hereby authorized to enter into contracts with private firms for services related or incidental to their respective functions and operations, through public bidding or negotiated contract. The contract cost may be paid from savings in the appropriations of the department, bureau, office or agency concerned: PROVIDED, That the execution of the service contracts shall not operate to automatically abolish or render vacant any existing occupied position in the contracting office or agency.\nPERSONAL SERVICE BENEFITS"}},{"id":"PH-H5185-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Funding of Personnel Benefits. The personnel benefits costs of government officials and employees shall be charged against the respective funds from which their compensations are paid All authorized supplemental or additional compensation, fringe benefits and other personal services costs of officials and employees whose salaries are drawn from special accounts or special funds, such as salary increases and adjustments, merit increases, incentive and service fees, vacation and sick leaves, retirement and life insurance premiums, compensation insurance premiums, health insurance (Medicare) premiums, HDM- contributions, hospitalization and medical benefits, scholarship and educational benefits, training and seminar expenses, all kinds of allowances, whether commutable or reimbursable, in cash or in kind, and other pers nel benefits and privileges authorized by law, including the payment of retirement gratuities, separation pay and terminal leave benefits, shall be charged against the corresponding fund from which their basic salaries are drawn and in no case shall such personnel benefits costs be charged against the General Fund of the national government.\nOfficials and employees on detail with other offices, including the representatives and support personnel of auditing units assigned to serve other offices or agencies, shall be paid their salaries, emoluments, allowances and the foregoing supplemental compensation fringe benefits and other personal services costs from the appropriations of their parent agencies, and in no case shall such be charged against the appropriations of the agencies where they are assigned or detailed, except when authorized by law."}},{"id":"PH-H5185-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Personnel Benefits Fund. The personnel benefits fund allocated in the respective budgets of departments, bureaus, offices and agencies shall be released in accordance with a Personnel Benefits Program to be approved by the President. The Employees (Compensation Insurance Premium Fund, the National Government Contributions to the Health Insurance (Medicare) Fund and the Employees' Share in the HDMF shall be released directly by the Department of Budget and Management to the Government Service Insurance System and the Home Development Mutual Fund. Savings generated in one department, bureau, office or agency shall be used to augment deficiencies in other departments, bureaus, offices or agencies."}},{"id":"PH-H5185-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Appropriations for Salary Standardization. The appropriations for salary standardization authorized respective budgets of departments, bureaus, offices and agencies in this Act shall be used only for the purpose of salary standardization pursuant to a law to be enacted by the Congress of the Philippines pursuant to the provisions of Section 5 of Article IX-B of the Constitution.\nSavings generated in one department, bureau, office or agency shall be used to augment deficiencies in other departments, bureaus, offices or agencies."}},{"id":"PH-H5185-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Representation and Transmission. The following officials and those of equivalent rank as may be determined by the Department of Budget and Management are hereby granted monthly commutable representation and transportation allowances payable from the programmed appropriations provided for their respective offices, not exceeding the rates indicated below, which shall apply to each type allowance:\na. At P2,500 for Secretaries or equivalent;\nb. At P1,750 for Department Undersecretaries or equivalent;\nc. At P1,500 for Assistance Secretaries, Bureau Directors, Department Assistance Regional Directors or equivalent;\nd. At P1,400 for Assistant Bureau Directors, Department Assistant Regional Directors, Bureau Regional Directors, Department Service Chiefs or equivalent;\ne. At P1,200 for Assistant Bureau Regional Directors or equivalent;\nf. At P1,100 for Chiefs of Division, identified as such in the Personal Services itemization.\nThe transportation allowance herein authorized shall not be granted to officials who are assigned a government vehicle or use government motor transportation, except as may be approved by the President of the Philippines. Unless otherwise provided by law, no amount appropriated in this Act shall be used to pay for representation and/or transportation allowances, whether commutable or reimbursable, which exceed the rates authorized under this Section. Previous administrative authorizations not consistent with the rates and conditions herein specified shall no longer be valid and payment shall not be allowed.\nAllowances of those officials who are receiving salaries form special are charged. Officials on details with other offices, including officials of the Commission on Audit assigned appropriations of their parent agencies."}},{"id":"PH-H5185-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Official Vehicles and Transport. Government motor transportation may be used by the following officials, including those who may be specifically authorized by the President of te Philippines, the President of the Senate with respect to the Senate, and the Speaker, with respect to the House of Representatives, with costs chargeable to the appropriations authorized for their respective offices:\na. The President of the Philippines;\nb. The Vice-President;\nc. The President of the Senate;\nd. Speaker of the House of Representatives;\ne. The Chief Justice of the Supreme Court;\nf. The Secretaries, Undersecretaries and officials of equivalent rank;\ng. The Presiding Justice of Court of Appeals;\nh. Ambassadors, Ministers Plenipotentiary and Consuls in charge of Consulates, in their respective stations abroad;\ni. The Chief of Staff, the Vice-Chief of Staff, and the Commanding Generals of the major services of the Armed Forces of the Philippines; and\nj. The Heads of Constitutional Offices."}},{"id":"PH-H5185-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"Uniform and Clothing Allowance. The appropriations herein provided for each department, bureau, office or agency may be used for uniform and clothing allowance employees at not more than 500 each per annum. Savings in the appropriations for each department, bureau or office may be used for this purpose where no amount is specifically appropriated in this Act."}},{"id":"PH-H5185-A31","no":31,"noLabel":{"en":"Section 31."},"text":{"en":"Hazard Duty Pay. Upon recommendation of the Department Head and approval of the Department of Budget and Management, hazard pay may be allowed to officials and employees who are actually assigned in hardship or difficult areas, distressed or isolated stations, prison camps, mental hospitals, radiation-exposed clinics or laboratories, or disease-infested areas or i areas declared under state of calamity or emergency for the duration thereof which expose them to great danger, contagion, radiation, volcanic activity/eruption, occupational risk or perils to life, chargeable to savings in the appropriations of the department /agency concerned, which shall not be less than P50 no more than P150 each per month, except in cases where the rates are specifically provided for under special laws, charters or enabling acts, in which case such rates shall govern, or where more incentives are needed to attract applicants, in which case the sum maybe augmented at rates to be determined by the Department Heads as may may be necessary: PROVIDED, That hazard pay by reason of strife-torn or embattled areas shall be subject to the certification issued by the Secretary of National Defense and the rates thereof shall be determined by the Secretary of National Defense. The Secretary of National Defense. The Secretary of Budget and Management and the Secretary of National Defense shall review from time to time authorizations for the payment of hazard duty pay in strife-torn and embattled areas earlier issued and shall terminate such authorizations in areas where conditions no longer justify the continuation of hazard duty pay."}},{"id":"PH-H5185-A32","no":32,"noLabel":{"en":"Section 32."},"text":{"en":"Honoraria. Departments, bureaus, offices or agencies are authorized to use their respective appropriations for payment of honoraria as compensation for services rendered by researchers, experts and specialists who are acknowledged authorities in their field of specialization, at such rates as the Department of Budget and Management may authorize, unless otherwise specifically provided by law."}},{"id":"PH-H5185-A33","no":33,"noLabel":{"en":"Section 33."},"text":{"en":"Incentive and Services Fees. Public offices, including government owned/or other benefits accruing to any government employee, any amount for the payment of obligations except those due and owing to public lending institutions such as the PNB, GSIS, and to savings and Loans Associations exclusively organized for, and managed by, government employees. Deductions under this Act shall however only be allowed if the policies, credit or loans issued/granted by private companies and if the service fees that are paid to the collecting agency represents a fair share in the savings of the creditor or obligor from the cost of collection: PROVIDED, That no deduction shall be allowed which will reduce the employee's take home pay below one thousand pesos after effecting all other statutory deductions: PROVIDED FURTHER, That the agencies and offices with existing deduction arrangements with private lenders, shall continue such deductions until the credits/loans outstanding or the premiums of the policies in force at the date of the passage of this Act shall have been fully paid: PROVIDED, FINALLY, that the PNB, GSIS and other government financial institutions are directed to immediately undertake the necessary steps to provide loan facilities equivalent to those presently extended to public employees by private companies with existing deduction arrangements.\nService fees collected shall be deposited with the national or public financial institution treasury and shall accrue in the general fund, pursuant to Section 50 of P.D. No. 1177. Such fees may be made available for payment of incentive or service fees to employees who are actually and directly involved in the collection: PROVIDED HOWEVER, That the share of any employee may not, in the aggregate exceed fifty (50%) percent of his annual salary.\nAny surplus of service fees deposited with the National Treasury pursuant to the provisions of the second paragraph hereof, shall form part of a provident fund to be established by the agency in favor of all its employees, which shall be administered pursuant to a set of uniform rules and regulations which the Office of the President shall promulgate."}},{"id":"PH-H5185-A34","no":34,"noLabel":{"en":"Section 34."},"text":{"en":"Special Counsel Allowance. Lawyer-personnel in the legal staffs of departments, bureaus, offices or agencies of the national government appearing in Court as special counsel in collaboration with the Solicitor General or Fiscals concerned are hereby authorized an allowance of P150 for each appearance, chargeable to savings in the appropriations allotted for personal service of their respective offices, but not exceeding P600 a month."}},{"id":"PH-H5185-A35","no":35,"noLabel":{"en":"Section 35."},"text":{"en":"Quarters Allowance. Except as may be authorized by law, government officials and employees who, by virtue of their positions, are furnished free quarters or are charged only a nominal rate in government-owned buildings, such as dormitories or living quarters in hospitals, state colleges, universities and schools, foreign posts and elsewhere, shall forfeit entitlement to any quarters allowance. In case where portions of rented buildings are authorized to be utilized tor officials' quarters, the excess of rental cost over the quarters allowance of the officials shall be borne by the officials or employees concerned. Those who enjoy free quarters in government-owned or rented buildings but who are not entitled to quarters privileges, shall be charged the corresponding cost of rentals therefor Unless fixed by law or regulations, the rate of quarters allowance or rental, as the case may be, shall be determined by the Department of Budget and Management."}},{"id":"PH-H5185-A36","no":36,"noLabel":{"en":"Section 36."},"text":{"en":"Compensation of Contractual Personnel. Heads of departments, bureaus, offices or agencies, when authorized in their respective appropriations as provided in this Act, may hire consultants, experts and other contractual personnel to perform specific vital activities or services which cannot be provided by the regular staff of the agency, limited to such period when their services are reasonably required and to activities that shall have a definite expected output. Such contractual personnel may be paid compensation inclusive of fees, honoraria, per diems compensation and allowances not exceeding 120 percent of the minimum salary of an equivalent position in the National Classification and Compensation Plan, except as may be authorized by the Department of Budget and Management in the following instances: (a) when the consultant or expert is an acknowledged authority in his field of specialization; and (b) where the consultant or expert is hired to perform a specific activity or service that requires technical skill and expertise which local labor force cannot provide, or if such expertise is available, the supply is limited: PROVIDED, That in no case shall such compensation exceed the salary of his immediate superior, except as may be otherwise approved jointly by the Civil Service Commission and the Department of Budget and Management."}},{"id":"PH-H5185-A37","no":37,"noLabel":{"en":"Section 37."},"text":{"en":"Use of Appropriations for Retirement Gratuity and Terminal Leave. Release of appropriations authorized in this Act to cover retirement gratuity benefit claims shall be made on the basis of creditable services as computed by the Government Service Insurance System in accordance with the provisions of existing retirement laws. Unless otherwise authorized by law, no amount appropriated in this Act shall be used for payment of retirement gratuity Linder the provisions of Section 12(c) of C.A. No. 186, as amended by R.A. No. 1616, and terminal leave benefits of retiring officials and employees which include in the computation thereof additional compensation as defined under retirement laws such as bonuses, per diems, allowances and overtime pay, or salary, pay or compensation given in addition to the base pay of the position or rank as fixed by law or regulation.\nSavings generated in one department, bureau, office or agency shall be used to augment deficiencies in other departments, bureaus, offices or agencies. The rules and regulations to implement this Section shall be issued jointly by the Department of Budget and Management, the Government Service Insurance System and the Civil Service Commission."}},{"id":"PH-H5185-A38","no":38,"noLabel":{"en":"Section 38."},"text":{"en":"Unauthorized Pre-Retirement Promotions and Salary Increases. No portion of the appropriations provided in this Act shall be used for automatic promotions or for salary increases and adjustments granted to retiring officials and employees, which are not authorized by law and duly formalized a in National Compensation Circular.\nThe rules and regulations to implement this Section shall be issued jointly by the Civil Service Commission and the Department of Budget and Management."}},{"id":"PH-H5185-A39","no":39,"noLabel":{"en":"Section 39."},"text":{"en":"Personal Liability of Officials for Payment of Unauthorized Personal Services Cost. No official or employee of the National Government, including those of government-owned and/or controlled corporations, shall be paid any unauthorized personal services benefits charged against the appropriations in this Act, other appropriations laws or income of the government.\nThe payment of any unauthorized personal services benefits in violation of this Section is null and void. The erring officials and employees shall be subject to disciplinary action Linder the provisions of Sections 49 and 87 of P.D. No. 1177 and to appropriate criminal action under existing penal laws.\nLOCAL GOVERNMENT UNITS"}},{"id":"PH-H5185-A40","no":40,"noLabel":{"en":"Section 40."},"text":{"en":"Sharing of National Revenues. The appropriations herein authorized for local government revenue sharing shall be released in accordance with the procedure prescribed under P.D. Nos. 144 and 436, as amended. Compliance with the sharing formula as provided by law shall be determined in accordance with the rules and regulations established by the Department of Budget and Management pursuant to P.D. Nos. 144 and 436, as amended, taking into account all funds allocated and released for local government units, except for the budgetary aid fund herein appropriated pursuant to Item No. 7 of P.D. No. 144."}},{"id":"PH-H5185-A41","no":41,"noLabel":{"en":"Section 41."},"text":{"en":"Release of Appropriations to Local Government Units. Funds appropriated herein for local government units shall be released only after tie approval of their respective budgets pursuit to the provisions of P.D. No. 1375, except as may be authorized by the Department of Local Government and the Department of Budget and Management.\nADMINISTRATIVE PROCEDURES"}},{"id":"PH-H5185-A42","no":42,"noLabel":{"en":"Section 42."},"text":{"en":"Training Programs. Departments, bureaus, offices or agencies shall review and formulate their training programs to make the same responsive to the organizational needs and manpower requirements of agencies and the need to train personnel in skills and attitudes. Such training programs shall be consistent with the rules and regulations issued by the Training Coordination Committee created under LDI No. 754, which shall review and evaluate training activities."}},{"id":"PH-H5185-A43","no":43,"noLabel":{"en":"Section 43."},"text":{"en":"Direct Release of Funds to Regional Offices. Funds allotted for regional offices but included in the budgets of their central offices or which are specifically allocated for the different regions shall be released directly to said regional offices. Imposition of any retention or deduction as reserves shall not be allowed except as may be authorized by the Department of Budget and Management. For this purpose, the Department of Budget and Management shall identify by region the expenditure programs of agencies in the national government budget and shall release funds intended for them in accordance with the approved regional distribution of expenditures specifying the region of destination. Copies of fund releases to the said regional offices shall be furnished the House Committee on Appropriations and the Senate Committee on Finance."}},{"id":"PH-H5185-A44","no":44,"noLabel":{"en":"Section 44."},"text":{"en":"Prohibition Against Deduction/Retention of Allotment. Fund releases from appropriations provided in this Act for any function/project shall be transmitted intact or in full to the office or agency concerned and no retention or deduction as reserves or overhead shall be made, except as authorized by law or upon direction of the President of the Philippines. The Commission on Audit shall ensure compliance with this provision to the extent that sub-allotments by departments and/or central agencies to their subordinate offices are in conformity with allocations in budgetary Advice of Allotments issued by the Department of Budget and Management."}},{"id":"PH-H5185-A45","no":45,"noLabel":{"en":"Section 45."},"text":{"en":"Work and Financial Plan. All departments, bureaus, offices and agencies, including government-owned and/or controlled corporations, shall submit their respective Work and Financial Plans as may be required by the Department of Budget and Management as the basis for the release of allotments, and funding warrants.\nThe Work and Financial Plan shall be prepared in accordance with the form and content as prescribed by the Secretary of Budget and Management.\nNo deviations shall be allowed from the approved Wort; and Financial Plan except upon prior approval of the Secretary of Budget and Management.\nAgencies, however may augment an item of expenditure within Maintenance and Other Operating Expenses (MOE) from savings in other items of MOE not exceeding twenty five percent (25/C) of the appropriated amount to be augmented."}},{"id":"PH-H5185-A46","no":46,"noLabel":{"en":"Section 46."},"text":{"en":"Submission of Operating Budgets and Financial Statements. All government-owned and/or controlled corporations shall submit to the House Committee on Appropriations, the Senate Committee on Finance, and the Department of Budget and Management, their respective operating budgets recommended for consideration and final approval of the President, together with the financial statements, including plans and programs, targets and other reports as may be required from time to time. The annual reports shall be prepared as herein provided and submitted on or before March 31 of the succeeding year."}},{"id":"PH-H5185-A47","no":47,"noLabel":{"en":"Section 47."},"text":{"en":"Use of the Funds Allotted for Budgetary Support to Government Corporations. The amounts herein appropriated for budgetary support to government owned and/or controlled corporations which are included under the budgets of the Department/Offices to which these are attached, may be used to support operating expenses, loans outlays and equity investments or trust funds to be administered by government-owned and/or controlled corporations: PROVIDED, That payment of salaries, allowances and other benefits shall be in accordance with P.D. No. 985 and that retirement gratuities paid from this fund shall be computed in accordance with the rates, conditions and procedures prescribed under existing retirement laws, rules and regulations: PROVIDED, FURTHER, That in no case shall equity investments be used for salaries, allowances, retirement gratuities and other benefits: AND PROVIDED, FINALLY, That releases shall be subject to Section 40 of P.D. No. 1177 and LOImp. No. 29."}},{"id":"PH-H5185-A48","no":48,"noLabel":{"en":"Section 48."},"text":{"en":"Fund Releases for Budgetary Support to Government Corporations. FiJids herein appropriated -for budgetary support to government-owned and/or controlled corporations shall be under the administration of the Department of Budget and Management. Said funds will be directly released to the recipient corporation through the B-ireau of Treasury. All requests for fund releases for subsidies or capital investments to government corporations A11 emanate from their respective Boards through the Departments to which they are attached."}},{"id":"PH-H5185-A49","no":49,"noLabel":{"en":"Section 49."},"text":{"en":"Offsets Against Budgetary Support to Government Corporations. The appropriations herein authorized for budgetary support to government corporations may be used by the Bureau of the Treasury for the corporate payments of the five percent (SX) dividend under Executive Order No. 518, as well as repayments for the loans relent to corporate obligations guaranteed by the Government of the Republic of the Philippines. Furthermore, if the total level of actual revenues at the end of 1988, liquid assets (i.e. cash and short term investments), bond investments and other fund sources of a government corporation exceed the corresponding projections consistent with the formulation of the 1989 budgetary support program, then the excess may be deducted from the said program and may be reduced to the extent of such favorable effect."}},{"id":"PH-H5185-A50","no":50,"noLabel":{"en":"Section 50."},"text":{"en":"Submission of Quarterly Reports. Within 15 days after the end of each quarter, each department, bureau, office or agency shall submit a quarterly report to the House Committee on Appropriations and the Senate Committee on Finance, copy furnished the Department of Bidget and Management, on their cumulative allotments, obligations incurred/liquidated, total disbursements unliquidated obligations, unobligated and unexpended balances, and the results of expended appropriations.\nThe quarterly report shall include detailed statements on the disbursements and utilization of appropriations for the purchase of motor vehicles and equipment, capital investment outlays, as well as appropriations earmarked and released for rentals, travels, petroleum, oil and lubricants, water illumination and power services, and telephone and other communication services."}},{"id":"PH-H5185-A51","no":51,"noLabel":{"en":"Section 51."},"text":{"en":"Unauthorized Organizational Changes. Unless otherwise created by law or directed by the President of the Philippines, no organizational unit or key position in any department or agency shall be authorized in their respective organizational structures and be funded from appropriations provided by this Act."}},{"id":"PH-H5185-A52","no":52,"noLabel":{"en":"Section 52."},"text":{"en":"Implementation of Construction Projects. Construction projects funded from capital outlays authorized in this Act under the various departments, bureaus, offices or agencies of the national government, including the construction of buildings for state universities, colleges, schools, hospitals, sanitaria, health centers and health stations, roads and bridges, shall be implemented only in accordance with the appropriate standards and specifications for the planning, survey, design and construction of the project as prescribed by the Department of Public Works and Highways or the Department of Transportation and Communications, through either of said departments as the case may be. In addition, land use and zoning guidelines as prescribed by existing laws, rules and regulations shall be strictly observed. In the implementation of the construction projects. Sections 2, 3, 4, 5, 6, 7, 9, 10 and 12 of Executive Order No. 182, entitled \"Rationalizing Public Works Measures, Appropriating Funds for Public Works, and for Other Purposes\", and other legislations on public works shall be strictly complied with."}},{"id":"PH-H5185-A53","no":53,"noLabel":{"en":"Section 53."},"text":{"en":"\"Realignment\" of Capital Outlays and Public Works Projects. The amount appropriated in this Act for construction replacement, rehabilitation and completion of school buildings, hospitals, sanitaria, health centers, clinics, herbal processing plants, warehouses, and health stations, as well as waterworks/supply, and other public works projects under the FY 1989 Infrastructure Program may be \"realigned\": PROVIDED, That such \"realignment\" shall be made within thirty (30) days after the approval of this Act: PFOVIDED, FLRTI-ER, That such \"realignment\" is within the congressional district for which the funds were originally allocated: PMD PROVIDED, FURTHERMORE, That the \"realignment\" shall be for projects within the same category and shall not exceed the total amount originally allocated for the congressional district: PND PROVIDED, FIUW-LY, That the \"realignment\" shall be made upon the initiative and consent of the representative of the district concerned and with the concurrence of any one of the following: the District or City Engineer, the Regional Director or Secretary of the Department concerned."}},{"id":"PH-H5185-A54","no":54,"noLabel":{"en":"Section 54."},"text":{"en":"Release of Funds. Release of funds for NALGU, construction repair and maintenance, rehabilitation, replacement, completion, betterment or improvement of roads and bridges, port works, flood control, waterworks/supply and government buildings and structures shall be released with at least seven (7) days prior written notice to the representative of the district concerned."}},{"id":"PH-H5185-A55","no":55,"noLabel":{"en":"Section 55."},"text":{"en":"Prohibition Against the Restoration or Increase of Recommended Appropriations Disapproved and/or Reduces by Congress. No item of appropriation recommended by the President in the budget submitted to Congress pursuant to Article VI, Section 22 of the Constitution which has been disapproved or reduced in this Act shall be restored or increased by the use of appropriations authorized for other purposes in this Act by augmentation. An item of appropriation for any purpose recommended by the President in the budget shall be deemed to have been disapproved by Congress if no corresponding appropriations for the specific purpose is provided in this Act."}},{"id":"PH-H5185-A56","no":56,"noLabel":{"en":"Section 56."},"text":{"en":"Separability Clause. If for any reason any section or provision of this Act is declared unconstitutional or invalid, other sections or provisions hereof which are not affected thereby shall continue to be in full force and effect."}},{"id":"PH-H5185-A57","no":57,"noLabel":{"en":"Section 57."},"text":{"en":"Effectivity. The provisions of this Act shall take effect on January one, nineteen hundred and eighty-nine, unless otherwise provided herein.\nApproved.\nPresidential Veto Message\nSummary of New Appropriations hindipapwedengipost"}}],"pack":"ph-p73"};
  FT["PH-H5186"] = {"id":"PH-H5186","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6689_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Tigaon North Central Elementary School in the Municipality of Tigaon, Province of Camarines Sur, to Felix Plazo Memorial Elementary School","orig":"An Act Changing the Name of the Tigaon North Central Elementary School in the Municipality of Tigaon, Province of Camarines Sur, to Felix Plazo Memorial Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 6689","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-02-10","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6689_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5186-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Tigaon North Central Elementary School located in the Municipality of Tigaon, Province of Camarines Sur, is hereby changed to Felix Plazo Memorial Elementary School."}},{"id":"PH-H5186-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without executive approval, February 10, 1989"}}],"pack":"ph-p73"};
