  FT["PH-H5189"] = {"id":"PH-H5189","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6692_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Declaring September Twenty-Eight as Balangiga Encounter Day and a Special Non-Working Holiday in the Province of Eastern Samar","orig":"An Act Declaring September Twenty-Eight as Balangiga Encounter Day and a Special Non-Working Holiday in the Province of Eastern Samar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6692","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-02-10","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6692_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5189-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"September twenty-eight of every year is hereby declared as Balangiga Encounter Day and a special non-working holiday in the province of Eastern Samar to commemorate the Balangiga encounter."}},{"id":"PH-H5189-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p73"};
  FT["PH-H5190"] = {"id":"PH-H5190","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6693_1989.html","fetchedAt":"2026-10-06","articleCount":1,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Renaming the Barangay Bulwagan Elementary School in the Municipality of Hinoba-An, Province of Negros Occidental, as the Paz Vda De Escanilla Elementary School","orig":"An Act Renaming the Barangay Bulwagan Elementary School in the Municipality of Hinoba-An, Province of Negros Occidental, as the Paz Vda De Escanilla Elementary School"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 6693","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-02-10","completenessNote":"全文，共 1 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6693_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5190-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Barangay Bulwagan Elementary School locates in Barangay Bulwagan, Municipality of Hinoba-an, Province of Negros Occidental, is hereby renamed as the Paz Vda de Escanilla Elementary School."}}],"pack":"ph-p73"};
  FT["PH-H5191"] = {"id":"PH-H5191","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6694_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Navalan Elementary School in Barangay Navalan, Municipality of Tukuran, Province of Zamboanga, Del Sur, to Margarito V. Lagare Memorial Elementary School","orig":"An Act Changing the Name of the Navalan Elementary School in Barangay Navalan, Municipality of Tukuran, Province of Zamboanga, Del Sur, to Margarito V. Lagare Memorial Elementary School"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 6694","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-02-10","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6694_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5191-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Navalan Elementary School in Barangay Navalan, Municipality of Tukuran, Province of Zamboanga del Sur, is hereby changed to Margarito V. Lagare Memorial Elementary School."}},{"id":"PH-H5191-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p73"};
  FT["PH-H5192"] = {"id":"PH-H5192","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6695_1989.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Renaming the Tumaga Elementary School in Zamboanga City as the Catalina Vda. De Jalon Memorial School","orig":"An Act Renaming the Tumaga Elementary School in Zamboanga City as the Catalina Vda. De Jalon Memorial School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 6695","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-02-10","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6695_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5192-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Tumaga Elementary School located in Barangay Tumaga, Zamboanga City, is hereby renamed as the Catalina Vda. de Jalon Memorial School."}},{"id":"PH-H5192-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p73"};
  FT["PH-H5193"] = {"id":"PH-H5193","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1989/ra_6696_1989.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Naming a National Highway From the Municipality of Pavia Up to the Municipality of Janiuay, Province of Iloilo, as the Tomas Confesor Highway","orig":"An Act Naming a National Highway From the Municipality of Pavia Up to the Municipality of Janiuay, Province of Iloilo, as the Tomas Confesor Highway"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6696","issuingBody":"Congress of the Philippines","promulgatedDate":"1989-02-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1989/ra_6696_1989.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5193-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The national highway starting from Km. 10 + 000 in the Municipality of Pavia to Km. 33 + 000 in the Municipality of Janiuay shall be known as the Tomas Confesor Highway."}},{"id":"PH-H5193-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Any law, ordinance, administrative order, designation or identification shall be considered repealed or modified accordingly."}},{"id":"PH-H5193-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p73"};
